## 1. COMPREENSÃO DO PROBLEMA

A casa é uma árvore: há `N` salas, `N - 1` túneis e é possível chegar de qualquer sala a qualquer outra. Ao adicionar um túnel entre duas salas, o ciclo criado é formado pelo caminho único entre elas na árvore mais o novo túnel.

Assim, se a distância entre as salas escolhidas é `d`, o ciclo tem `d + 1` salas. Portanto, precisamos encontrar:

- o diâmetro da árvore, isto é, a maior distância entre duas salas;
- o número de pares de salas cuja distância é igual ao diâmetro.

Cada par de salas corresponde a uma maneira de construir o ciclo. Como `N ≥ 3`, a distância máxima é pelo menos 2, então os pares considerados não são túneis já existentes.

A entrada contém um único caso de teste. A saída deve ter duas linhas: o comprimento máximo do ciclo e a quantidade de ciclos com esse comprimento. Não há limites explícitos de tempo ou memória; `N ≤ 50000`. A árvore é conectada por definição, e os identificadores são de `1` a `N`.

## 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

Encontramos o diâmetro com duas buscas em largura:

1. Partindo de uma sala qualquer, encontramos uma sala mais distante, `A`.
2. Partindo de `A`, encontramos uma sala mais distante, `B`. A distância entre `A` e `B` é o diâmetro `D`.

A segunda busca também guarda os pais, permitindo reconstruir o caminho de diâmetro e identificar seu centro.

A contagem depende da paridade de `D`:

- **`D` par:** existe um centro em uma sala. Para cada ramo que sai do centro, contamos quantas salas estão à distância `D/2`. O total de pares válidos é a soma dos produtos entre contagens de ramos distintos.
- **`D` ímpar:** o centro é uma aresta. Contamos, em cada lado da aresta, quantas salas estão à distância `D/2` do respectivo extremo. O total é o produto dessas duas contagens.

As buscas e contagens percorrem a árvore um número constante de vezes, portanto a complexidade é **O(N)** em tempo e **O(N)** em espaço. A lista de adjacência é armazenada em arrays.

## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

static int n;
static int *head;
static int *to;
static int *next_edge;
static int edge_count;

static void add_edge(int u, int v) {
    to[edge_count] = v;
    next_edge[edge_count] = head[u];
    head[u] = edge_count++;
}

static int bfs(int start, int *dist, int *parent, int *queue) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
    }

    int front = 0;
    int back = 0;

    dist[start] = 0;
    if (parent != NULL) {
        parent[start] = 0;
    }
    queue[back++] = start;

    int farthest = start;

    while (front < back) {
        int u = queue[front++];

        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent != NULL) {
                    parent[v] = u;
                }
                queue[back++] = v;
            }
        }
    }

    return farthest;
}

/* Conta as salas à distância target de start, sem atravessar forbidden. */
static long long count_at_distance_in_side(
    int start, int forbidden, int target,
    int *parent, int *depth, int *queue
) {
    int front = 0;
    int back = 0;
    long long count = 0;

    parent[start] = forbidden;
    depth[start] = 0;
    queue[back++] = start;

    while (front < back) {
        int u = queue[front++];

        if (depth[u] == target) {
            count++;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (v == parent[u]) {
                continue;
            }

            parent[v] = u;
            depth[v] = depth[u] + 1;
            queue[back++] = v;
        }
    }

    return count;
}

int main(void) {
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    head = malloc((n + 1) * sizeof(int));
    to = malloc(2 * (n - 1) * sizeof(int));
    next_edge = malloc(2 * (n - 1) * sizeof(int));

    int *dist = malloc((n + 1) * sizeof(int));
    int *parent = malloc((n + 1) * sizeof(int));
    int *queue = malloc((n + 1) * sizeof(int));
    int *path = malloc((n + 1) * sizeof(int));

    if (head == NULL || to == NULL || next_edge == NULL ||
        dist == NULL || parent == NULL || queue == NULL || path == NULL) {
        free(head);
        free(to);
        free(next_edge);
        free(dist);
        free(parent);
        free(queue);
        free(path);
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    edge_count = 0;

    for (int i = 0; i < n - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x, y);
        add_edge(y, x);
    }

    int a = bfs(1, dist, NULL, queue);
    int b = bfs(a, dist, parent, queue);
    int diameter = dist[b];

    /* Reconstrói o caminho de diâmetro, de b até a. */
    int path_length = 0;
    for (int x = b; x != 0; x = parent[x]) {
        path[path_length++] = x;
    }

    long long ways = 0;

    if (diameter % 2 == 0) {
        int radius = diameter / 2;
        int center = path[radius];

        int *branch = malloc((n + 1) * sizeof(int));
        long long *count_by_branch = calloc(n + 1, sizeof(long long));

        if (branch == NULL || count_by_branch == NULL) {
            free(branch);
            free(count_by_branch);
            free(head);
            free(to);
            free(next_edge);
            free(dist);
            free(parent);
            free(queue);
            free(path);
            return 0;
        }

        int front = 0;
        int back = 0;
        queue[back++] = center;
        parent[center] = 0;
        branch[center] = 0;

        while (front < back) {
            int u = queue[front++];

            if (dist[u] == radius && u != center) {
                count_by_branch[branch[u]]++;
            }

            for (int e = head[u]; e != -1; e = next_edge[e]) {
                int v = to[e];
                if (v == parent[u]) {
                    continue;
                }

                parent[v] = u;
                branch[v] = (u == center) ? v : branch[u];
                dist[v] = dist[u] + 1;
                queue[back++] = v;
            }
        }

        long long seen = 0;
        for (int v = 1; v <= n; v++) {
            ways += seen * count_by_branch[v];
            seen += count_by_branch[v];
        }

        free(branch);
        free(count_by_branch);
    } else {
        int radius = diameter / 2;
        int u = path[radius];
        int v = path[radius + 1];

        long long left_count =
            count_at_distance_in_side(u, v, radius, parent, dist, queue);
        long long right_count =
            count_at_distance_in_side(v, u, radius, parent, dist, queue);

        ways = left_count * right_count;
    }

    printf("%d\n%lld\n", diameter + 1, ways);

    free(head);
    free(to);
    free(next_edge);
    free(dist);
    free(parent);
    free(queue);
    free(path);

    return 0;
}
```

## 4. RETROSPECTO E VERIFICAÇÃO

- No primeiro exemplo, o diâmetro é 3; logo, o ciclo máximo tem 4 salas. Há 2 pares de salas a essa distância.
- No segundo exemplo, o diâmetro é 4; logo, o ciclo máximo tem 5 salas. A contagem dos pares entre ramos distintos resulta em 6.
- Árvores com diâmetro par são contadas por ramos do centro; árvores com diâmetro ímpar são contadas pelos dois lados da aresta central.
- A implementação usa filas iterativas, evitando problemas de pilha em árvores muito profundas. O tempo e a memória são O(N), adequados para `N ≤ 50000`.

